preConditionHook:
// The bucket's mechanized Brooks spike: every one of the last N bars is a
// with-trend bar whose body is at least bodyFraction of its own range.
// All-of-N, written the way ConsecutiveUpBars writes it -- start true and let
// any failing bar clear the flag -- so the loop runs unconditionally and
// EasyLanguage's lack of short-circuiting cannot matter. Both sides are
// computed here rather than in the conditions for the same reason.
//
// At bodyFraction = 0 the body test is c - o >= 0, which the strict
// c > o already implies, so the rule reproduces ConsecutiveUpBars bar
// for bar; the body size is the whole content of 'strong'.
//
// The flags are class members and so persist across bars: both are reset at
// the top of the hook, not relied on to start true.
allStrong = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    if (el_le(close[kk], open[kk])) allStrong = false;
    if (el_lt(close[kk] - open[kk], bodyFraction * (high[kk] - low[kk]))) allStrong = false;
}
allStrongDown = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    if (el_ge(close[kk], open[kk])) allStrongDown = false;
    if (el_lt(open[kk] - close[kk], bodyFraction * (high[kk] - low[kk]))) allStrongDown = false;
}
